      if ((input as HTMLInputElement).checked) {
        (input as HTMLInputElement).checked = false;
        input.dispatchEvent(new Event('change', { bubbles: true }));
        cleared++;
      }
    } else if (el.tagName.toLowerCase() === 'select') {
      if ((input as HTMLSelectElement).value) {
